export const meta = {
 "title": "Abolition Problems",
 "subtitle": "Verses for the Abolitionist to Explain",
 "eyebrow": "A Lexicon",
 "intro": [
  "Those who teach that the Law ended at the cross ask Law-keepers to explain a handful of verses from Galatians, Colossians, Ephesians, and Romans. This lexicon reverses the exchange. It gathers the passages an abolished Law cannot account for: the Messiah's own words on the Law, the apostles' commands, the assemblies keeping Sabbath and feasts after the cross, sin defined as lawlessness, and the statutes Yahuah called everlasting.",
  "The verses fall under thirteen problems in four parts. The opponents' own proof texts are answered in a separate tracker and are not repeated here. The Old Testament section admits only verses that speak of the Law lasting for ever or going forth in the age of the Messiah; praise of the Law, which no one disputes, is left out. Deliverance comes first, through the blood of the Messiah; the Law is the walk that follows. Nothing here teaches that anyone is saved by keeping the Law. Everything here shows that the saved are not released from it.",
  "Quotations follow the King James Version with the names restored: Yahuah for the Father, Yahushua for the Son, Messiah for Christ, and Master where kurios refers to Yahushua. Hebrew feast names stand in place of their Greek and English substitutes."
 ]
};

export const parts = [
 {
  "id": 1,
  "label": "Part One",
  "title": "The Messiah's Own Words",
  "text": "Yahushua is the first authority on whether the Law continues. In the Gospels He affirms it, raises its standard, defends it against tradition, and lives it out with His household. None of His words sets an end date at His death."
 },
 {
  "id": 2,
  "label": "Part Two",
  "title": "The Apostles' Letters",
  "text": "The letters were written years and decades after the cross. If the Law had ended, the apostles were the ones to say so. Instead they define love by the commandments, define sin as lawlessness, call the Law holy and established, and repeat its commands to Gentile assemblies."
 },
 {
  "id": 3,
  "label": "Part Three",
  "title": "After the Cross and at the End",
  "text": "The common claim is that the Law died with the Messiah. Acts records the disciples and Paul keeping Sabbath, feasts, vows, and Temple worship long after the cross, Hebrews writes the same Law on the heart, and Revelation shows the commandments, the ark, and the song of Moses present at the close of the age."
 },
 {
  "id": 4,
  "label": "Part Four",
  "title": "The Old Testament Witness",
  "text": "Old Testament verses are admitted only when they carry the Law past Moses, past the cross, or into the age to come. The question from the notebook stands over this whole part: why would Yah bring back the Torah in the last days if it had been voided?"
 }
];

// problem.part points to parts[].id
export const problems = [
 {
  "id": 1,
  "title": "It Thinks What He Said Not to Think",
  "part": 1,
  "text": "Yahushua's own words are the first authority on whether the Law continues. Every statement below either affirms the Law, raises its standard, or sends His followers to keep it. None of them sets an end date at His death."
 },
 {
  "id": 2,
  "title": "It Defends Tradition Over the Commandment",
  "part": 1,
  "text": "Yahushua's sharpest conflicts were over the traditions of men, not over the Law. In every case He defends the commandment against the tradition, the reverse of what the pulpit claims."
 },
 {
  "id": 3,
  "title": "It Rejects the Walk He Set",
  "part": 1,
  "text": "The usual answer to these verses is that they happened before the cross. That answer asks a whole people who kept the Sabbath, the feasts, and the commandments all their lives to stop overnight, with no word from the Messiah or the apostles announcing it. The Gospels record His household keeping the Law, Yahushua keeping it Himself, and Yahushua sending the men He healed to obey Moses. Scripture shows no switch afterward. The women rested the day after His death “according to the commandment” (Luke 23:56). About ten years later Peter had never eaten anything unclean (Acts 10:14). About twenty-five years later the believers in Jerusalem numbered thousands, “all zealous of the law” (Acts 21:20). The walk recorded here is the walk believers are told to copy: “He that saith he abideth in him ought himself also so to walk, even as he walked” (1 John 2:6)."
 },
 {
  "id": 4,
  "title": "It Separates Love From the Commandments",
  "part": 2,
  "text": "John's letters were written decades after the cross. If the commandments had ended, John would have been the one to say so. Instead he makes commandment-keeping the test of knowing Yahuah."
 },
 {
  "id": 5,
  "title": "It Leaves Sin Without a Definition",
  "part": 2,
  "text": "The Greek anomia means without law. Where the New Testament names sin, iniquity, or the coming deceiver, it often uses this word. If the Law were gone, lawlessness could not be a sin."
 },
 {
  "id": 6,
  "title": "It Makes Paul Void What He Established",
  "part": 2,
  "text": "Paul is the apostle most quoted against the Law, yet his own words call it holy, spiritual, good, and established. These verses are the ones the abolition reading has to explain."
 },
 {
  "id": 7,
  "title": "It Ignores the Commandments the Apostles Repeat",
  "part": 2,
  "text": "When the apostles correct the assemblies, they reach for the commandments of Torah: the Ten Words, the laws of sexual purity, the laws of clean and unclean, and the laws of holiness. Each entry is a commandment repeated after the cross."
 },
 {
  "id": 8,
  "title": "It Ends at the Cross What Continued After It",
  "part": 3,
  "text": "The common claim is that the Law ended when the Messiah died. These verses record the disciples, the apostles, and the assemblies keeping Sabbath, feasts, vows, and Temple worship after the cross, many of them decades later. Each one is a problem for the claim that the Law died with Him."
 },
 {
  "id": 9,
  "title": "It Empties the New Covenant of Its Content",
  "part": 3,
  "text": "The new covenant is the Law moved inward, not the Law removed. The same promise is quoted twice in Hebrews."
 },
 {
  "id": 10,
  "title": "It Removes the Law Before Heaven and Earth Pass",
  "part": 3,
  "text": "The last book shows the commandments, the ark of the covenant, and the song of Moses present at the close of the age. It also completes the timeline of Matthew 5:18: the Law stands until heaven and earth pass away, and that passing is recorded only here."
 },
 {
  "id": 11,
  "title": "It Cuts Short What Yahuah Called Everlasting",
  "part": 4,
  "text": "Old Testament verses are admitted to this list only when they speak of the Law lasting beyond Moses, beyond the cross, or into the age to come. Each verse below attaches a time word to a statute: for ever, perpetual, everlasting, throughout your generations, or to a thousand generations. The problem for the abolitionist is simple: a statute Yahuah called everlasting cannot be given an expiration date by a later teacher."
 },
 {
  "id": 12,
  "title": "It Voids What the Prophets Send Forth in the Last Days",
  "part": 4,
  "text": "These verses speak of the Law in the age of the Messiah, the last days, and the restored kingdom. If the Law had been voided at the cross, these prophecies would describe Yahuah bringing back the very thing He had removed."
 },
 {
  "id": 13,
  "title": "It Does What the Prophets Warned Against",
  "part": 4,
  "text": "These verses expose the teachers and powers that alter, hide, or neglect the Law. They pair with Yahushua's woe on the lawyers in Luke 11:52 and with Daniel's little horn, who sets out to change times and law."
 }
];

